            remaining = rest[1]
        at_path = remaining.find('/')
        at_query = remaining.find('?')
        end = min(at_path, at_query)
        # Everything up to (but not including) the slash or question mark is the host.
        host = remaining[:end]
        # The path starts at the slash and goes until the next question mark or end.
        if at_path == -1:
