            else:
                host, rem = rest[:pos], rest[pos:]
        else:
            host, rem = rest[:pos], rest[pos:]
        pos = rem.find('?')
        if pos == -1:
            path, query = rem, ''
        else:
            path, query = rem[:pos], rem[pos+1:]
        return {'scheme': scheme.lower(), 'host': host, 'path': path, 'query': query}

