    def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
        cycle = red_duration + green_duration
        for arrival in arrivals:
            while True:
                rem = arrival % cycle
                if rem < red_duration:
                    break
                arrival += 1
            yield arrival
        return list(pedestrian_crossing_ticks.__wrapped__(arrivals, red_duration, green_duration))

